import React, {useState, useEffect} from 'react';


const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://oldmatecranes.com.au/'
};

const menu = {
  link1:{
    copy:'home',
    url: 'http://oldmatecranes.com.au/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};





function Menu() {


  const [open, setOpen] = useState(false);

  useEffect(() => {
    let handler = (e) =>{
      if(e.target){
      setOpen(false);
    }
    };

    document.addEventListener('mousedown', handler);
  });  


return(
  <section>
    <div className='container-fluid'>
    <h2 onClick={()=>{setOpen(!open)}}>hello</h2>      
    </div>
  </section>
)};

export default Menu;
